<?php
require_once __DIR__ . '/config.php';
require_once __DIR__ . '/arn_features.php';
arn_require_role(['client','user']);
$email=$_SESSION['email'];
$stmt=$pdo->prepare("SELECT ms.id,ms.asset_id,ms.asset_type,ms.last_service,ms.next_due,ms.maintenance_type,ms.status,ms.created_at FROM maintenance_schedules ms WHERE ms.client_email=? ORDER BY ms.next_due ASC,ms.id DESC");$stmt->execute([$email]);$rows=$stmt->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Maintenance | ARN QuickFix</title><link href="css/bootstrap.min.css" rel="stylesheet"><link href="css/style.css" rel="stylesheet"></head><body style="background:#F8FAFC"><div class="container py-5"><div class="d-flex justify-content-between align-items-center mb-4"><div><h2 class="fw-bold mb-1">My Maintenance Schedule</h2><p class="text-secondary mb-0">Preventive maintenance linked to your registered Asset IDs.</p></div><a href="client-dashboard.php" class="btn btn-outline-secondary rounded-pill">Back</a></div><div class="bg-white border rounded-4 shadow-sm p-4"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Asset ID</th><th>Asset Type</th><th>Last Service</th><th>Next Due</th><th>Maintenance Type</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="font-monospace fw-bold"><?=htmlspecialchars($r['asset_id'])?></td><td><?=htmlspecialchars($r['asset_type'])?></td><td><?=htmlspecialchars($r['last_service']??'—')?></td><td><?=htmlspecialchars($r['next_due'])?></td><td><?=htmlspecialchars($r['maintenance_type'])?></td><td><?=htmlspecialchars($r['status'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="text-center text-secondary py-5">No maintenance schedules yet.</td></tr><?php endif;?></tbody></table></div></div></div></body></html>
